// Guard suite for the A1.1 Wortliste migration (Course Factory Wave 2, PR B).
//
// migrations/2026-09-05-a1-1-wortliste.sql is generated by
// scripts/words-from-json.mjs from the reviewed addition/fix JSON. This test
// parses the GENERATED SQL (not the source JSON) so a hand-edit that breaks
// the re-run contract — an INSERT missing its WHERE NOT EXISTS guard, an
// UPDATE missing its IS NOT DISTINCT FROM guard, a plural regression back to
// the literal string "null" — fails here even if the JSON inputs stay clean.
// It also checks the article/plural display bug the migration's fixes exist
// to correct: src/utils/wordDisplay.js is the shared guard SrsTrainer.jsx and
// WordCard.jsx now both use.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { hasArticlePrefix, displayGerman } from '../src/utils/wordDisplay.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATION = 'migrations/2026-09-05-a1-1-wortliste.sql';

const sql = readFileSync(join(ROOT, MIGRATION), 'utf8');

// ---------------------------------------------------------------------------
// Parse the generated SQL back into statement blocks.
//
// Each INSERT/UPDATE is emitted by scripts/words-from-json.mjs as ONE
// contiguous statement ending at its own closing ");" or ";" — non-greedy so
// the match stops at the statement's own terminator, not a later one. String
// literals in the data can contain commas (e.g. "profession, job") but never
// a bare ";", so this is safe against the actual generated file.
// ---------------------------------------------------------------------------

const insertBlocks = [...sql.matchAll(/INSERT INTO public\.words[\s\S]*?\n\);/g)].map((m) => m[0]);
const updateBlocks = [...sql.matchAll(/UPDATE public\.words SET[\s\S]*?;/g)].map((m) => m[0]);

test('the migration has exactly 114 INSERT statements', () => {
  assert.equal(insertBlocks.length, 114);
});

test('every INSERT targets level a1.1', () => {
  for (const block of insertBlocks) {
    assert.match(block, /SELECT 'a1\.1',/, `INSERT missing/wrong level literal:\n${block}`);
    assert.match(block, /AND level = 'a1\.1'/, `INSERT's guard missing level = 'a1.1':\n${block}`);
  }
});

test('no INSERT carries the literal string "null" as a value', () => {
  for (const block of insertBlocks) {
    assert.ok(!block.includes("'null'"), `INSERT carries the literal string 'null':\n${block}`);
  }
});

test('every INSERT is guarded by WHERE NOT EXISTS on (german, level, category)', () => {
  for (const block of insertBlocks) {
    assert.match(
      block,
      /WHERE NOT EXISTS \(\s*SELECT 1 FROM public\.words WHERE german = '.*?' AND level = 'a1\.1' AND category = '.*?'\s*\)/,
      `INSERT missing a proper WHERE NOT EXISTS guard:\n${block}`,
    );
  }
});

test('the migration has exactly 51 UPDATE statements', () => {
  assert.equal(updateBlocks.length, 51);
});

test('every UPDATE is guarded by an IS NOT DISTINCT FROM on the old value', () => {
  for (const block of updateBlocks) {
    assert.match(
      block,
      /WHERE id = '[0-9a-f-]{36}'::uuid AND \w+ IS NOT DISTINCT FROM /,
      `UPDATE missing an IS NOT DISTINCT FROM guard:\n${block}`,
    );
  }
});

test('the migration is wrapped in BEGIN/COMMIT', () => {
  assert.match(sql, /^BEGIN;/m);
  assert.match(sql, /^COMMIT;/m);
});

test('every addition category from the source JSON appears in the migration', () => {
  // Pinned literally (not re-read from the review scratchpad, which is
  // ephemeral) so a category typo in a future regeneration is caught even if
  // the JSON that produced it is gone.
  const categories = [
    'Countries & Languages',
    'Jobs & Work',
    'Forms & Registration',
    'Drinks',
    'Time & Appointments',
    'Personal Pronouns',
  ];
  for (const cat of categories) {
    assert.ok(sql.includes(`'${cat}'`), `Migration is missing category "${cat}"`);
  }
});

// ---------------------------------------------------------------------------
// The article/plural display bug this migration's fixes address.
// ---------------------------------------------------------------------------

test('hasArticlePrefix detects a german value that already carries its article', () => {
  assert.equal(hasArticlePrefix('der', 'der Tag'), true);
  assert.equal(hasArticlePrefix('die', 'Die Zahl'), true); // case-insensitive
  assert.equal(hasArticlePrefix('der', 'Tag'), false);
  assert.equal(hasArticlePrefix(null, 'Tag'), false);
  assert.equal(hasArticlePrefix('der', null), false);
});

test('displayGerman prepends the article once, never twice', () => {
  assert.equal(displayGerman('der', 'Tag'), 'der Tag');
  assert.equal(displayGerman('der', 'der Tag'), 'der Tag'); // the bug: no double prefix
  assert.equal(displayGerman(null, 'sprechen'), 'sprechen');
  assert.equal(displayGerman('', 'Kaffee'), 'Kaffee');
});
